import { useEffect, useRef, useState } from "react";

export default function App() {
  const [duration, setDuration] = useState(25);
  const [secondsLeft, setSecondsLeft] = useState(25 * 60);
  const [isRunning, setIsRunning] = useState(false);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (!isRunning) return undefined;

    intervalRef.current = setInterval(() => {
      setSecondsLeft((current) => {
        if (current <= 1) {
          setIsRunning(false);
          return 0;
        }
        return current - 1;
      });
    }, 1000);

    return () => clearInterval(intervalRef.current);
  }, [isRunning]);

  const totalSeconds = duration * 60;
  const progress = totalSeconds === 0 ? 0 : (totalSeconds - secondsLeft) / totalSeconds;
  const radius = 128;
  const circumference = 2 * Math.PI * radius;
  const dashOffset = circumference * (1 - progress);
  const minutes = Math.floor(secondsLeft / 60);
  const seconds = secondsLeft % 60;

  const switchDuration = (nextDuration) => {
    setDuration(nextDuration);
    setSecondsLeft(nextDuration * 60);
    setIsRunning(false);
  };

  const toggleTimer = () => {
    if (secondsLeft === 0) {
      setSecondsLeft(totalSeconds);
      setIsRunning(true);
      return;
    }
    setIsRunning((running) => !running);
  };

  const resetTimer = () => {
    setSecondsLeft(totalSeconds);
    setIsRunning(false);
  };

  return (
    <main className="min-h-screen w-full bg-[#0b0d10] text-[#f4f1ea] flex items-center justify-center px-6 py-12 font-sans">
      <section className="w-full max-w-xl">
        <div className="mb-10 flex items-center justify-between border-b border-white/10 pb-5">
          <div>
            <p className="text-[11px] font-medium uppercase tracking-[0.28em] text-[#8d929b]">专注计时</p>
            <h1 className="mt-2 text-xl font-medium tracking-wide">番茄钟</h1>
          </div>
          <span className="rounded-full border border-[#ef6a4c]/30 bg-[#ef6a4c]/10 px-3 py-1 text-xs text-[#ff8a70]">
            {isRunning ? "进行中" : "准备就绪"}
          </span>
        </div>

        <div className="rounded-[28px] border border-white/[0.08] bg-[#111419] px-6 py-8 sm:px-10 sm:py-10">
          <div className="mb-8 flex justify-center">
            <div className="flex rounded-full bg-[#090b0e] p-1 ring-1 ring-white/[0.06]">
              {[25, 5, 15].map((option) => (
                <button
                  key={option}
                  type="button"
                  onClick={() => switchDuration(option)}
                  className={`min-w-20 rounded-full px-4 py-2 text-sm transition-colors duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#ef6a4c] ${
                    duration === option
                      ? "bg-[#252a31] text-white"
                      : "text-[#858b95] hover:text-white"
                  }`}
                >
                  {option} 分钟
                </button>
              ))}
            </div>
          </div>

          <div className="relative mx-auto aspect-square w-full max-w-[330px]">
            <svg
              viewBox="0 0 300 300"
              className="h-full w-full -rotate-90"
              aria-label="计时进度环"
            >
              <circle
                cx="150"
                cy="150"
                r={radius}
                fill="none"
                stroke="#20242b"
                strokeWidth="8"
              />
              <circle
                cx="150"
                cy="150"
                r={radius}
                fill="none"
                stroke="#ef6a4c"
                strokeWidth="8"
                strokeLinecap="round"
                strokeDasharray={circumference}
                strokeDashoffset={dashOffset}
                className="transition-[stroke-dashoffset] duration-700 ease-linear"
              />
            </svg>

            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-xs tracking-[0.22em] text-[#737985]">剩余时间</span>
              <div className="mt-3 font-mono text-6xl font-light tabular-nums tracking-tight text-[#f7f3ec]">
                {String(minutes).padStart(2, "0")}
                <span className="mx-1 text-[#555b65]">:</span>
                {String(seconds).padStart(2, "0")}
              </div>
              <span className="mt-3 text-xs text-[#8c929c]">
                {duration} 分钟专注
              </span>
            </div>
          </div>

          <div className="mt-9 flex items-center justify-center gap-5">
            <button
              type="button"
              onClick={resetTimer}
              className="rounded-full border border-white/10 px-5 py-3 text-sm text-[#a7acb4] transition-colors hover:border-white/20 hover:bg-white/[0.04] hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-[#ef6a4c]"
            >
              重置
            </button>
            <button
              type="button"
              onClick={toggleTimer}
              className="min-w-32 rounded-full bg-[#ef6a4c] px-7 py-3.5 text-sm font-semibold text-[#160b08] transition-colors hover:bg-[#ff7d61] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#ef6a4c] focus-visible:ring-offset-2 focus-visible:ring-offset-[#111419]"
            >
              {isRunning ? "暂停" : secondsLeft === 0 ? "重新开始" : "开始"}
            </button>
          </div>
        </div>

        <p className="mt-6 text-center text-xs leading-6 text-[#656b75]">
          选择时长，开始一段专注。保持简单，保持专注。
        </p>
      </section>
    </main>
  );
}
